# ADR-0009: Use a Small Single-Region AWS Deployment

- Status: Accepted
- Date: 2026-08-27

## Context

The agent needs an always-on WebSocket process during a one-week competition, durable reconciliation state, a public dashboard, private operator controls, and local reproducibility. Cost should remain low without sacrificing deterministic recovery.

## Decision

Deploy in one AWS region with Terraform:

- one Python 3.14 FastAPI/agent workload on ECS Fargate with a single active trading replica;
- DynamoDB for operational state, idempotency records, decisions, orders, positions, policies, and reporting projections;
- S3 for raw market-observation archives and analytical exports;
- a statically built Next.js TypeScript dashboard on S3 and CloudFront;
- an Application Load Balancer for the public reporting API and authenticated operator API;
- Cognito for operator authentication;
- Secrets Manager for Alpaca and model credentials;
- CloudWatch logs, metrics, and alarms; and
- an S3 Terraform backend using state locking and encryption.

Use `us-east-1` by default. Keep Alpaca integrations behind interfaces so local development can run against recorded data and the paper environment.

## Consequences

- The single trading replica avoids competing stream consumers and duplicate orders.
- Startup must reconcile durable state with Alpaca before entering `RUNNING` mode.
- The dashboard remains independently cacheable and cannot directly mutate trading state.
- Serverless persistence avoids database instance cost and removes relational database operations from the one-week deployment.
- Python 3.14 remains the default; downgrade only if a required production dependency demonstrably lacks support.

from __future__ import annotations

import hashlib
import json
from datetime import UTC, datetime, timedelta
from decimal import ROUND_CEILING, ROUND_FLOOR, Decimal
from typing import Protocol
from uuid import NAMESPACE_URL, uuid5

from catalyst_router.domain import (
    AgentMode,
    BrokerOrderSnapshot,
    DecisionRecord,
    InstrumentType,
    OrderExecution,
    OrderExecutionStatus,
    OrderPlan,
    PortfolioRiskState,
    QuoteSnapshot,
    RiskDecision,
    RiskDecisionStatus,
    Route,
    Side,
    TradeIntent,
)
from catalyst_router.ports import OperationalStore, PaperBroker
from catalyst_router.risk import RiskGovernor
from catalyst_router.training import FEATURE_SCHEMA, FeatureVector

_CENT = Decimal("0.01")


class IncumbentStrategy:
    """Conservative deterministic policy authorized for the first paper execution slice."""

    MAX_QUOTE_AGE = timedelta(seconds=5)
    MAX_FEATURE_AGE = timedelta(minutes=20)
    MAX_SPREAD_BPS = Decimal("15")

    def create_intent(
        self,
        vector: FeatureVector,
        quote: QuoteSnapshot,
        *,
        now: datetime | None = None,
    ) -> TradeIntent | None:
        observed_now = now or datetime.now(UTC)
        if vector.schema != FEATURE_SCHEMA or quote.symbol != vector.symbol:
            return None
        feature_age = observed_now - vector.observed_at
        quote_age = observed_now - quote.timestamp
        if not timedelta(0) <= feature_age <= self.MAX_FEATURE_AGE:
            return None
        if not timedelta(0) <= quote_age <= self.MAX_QUOTE_AGE:
            return None
        if quote.spread_bps > self.MAX_SPREAD_BPS:
            return None

        route = self.route(vector)
        if route is None:
            return None

        confidence = Decimal("0.85") if route is Route.REGIME_TREND else Decimal("0.80")
        entry_price = quote.ask_price.quantize(_CENT, rounding=ROUND_CEILING)
        stop_price = (entry_price * Decimal("0.98")).quantize(_CENT, rounding=ROUND_FLOOR)
        intent_id = str(
            uuid5(
                NAMESPACE_URL,
                f"incumbent-v1:{route}:{vector.symbol}:{vector.observed_at.isoformat()}",
            )
        )
        return TradeIntent(
            intent_id=intent_id,
            route=route,
            symbol=vector.symbol,
            instrument_type=InstrumentType.EQUITY,
            side=Side.BUY,
            confidence=confidence,
            entry_price=entry_price,
            stop_price=stop_price,
            expected_horizon_minutes=60 if route is Route.LIQUIDITY_REVERSION else 240,
            exposure_group="us-equity:long",
            quote_age_seconds=Decimal(str(quote_age.total_seconds())),
            data_quality_passed=True,
        )

    @staticmethod
    def route(vector: FeatureVector) -> Route | None:
        if vector.schema != FEATURE_SCHEMA:
            return None
        features = dict(zip(vector.names, vector.values, strict=True))
        if vector.symbol in {"SPY", "QQQ"} and (
            features["return_1"] > 0
            and features["return_4"] >= 0.002
            and features["return_12"] >= 0.005
            and features["close_location_20"] >= 0.2
        ):
            return Route.REGIME_TREND
        elif vector.symbol not in {"SPY", "QQQ"} and (
            features["return_1"] >= 0.0005
            and features["relative_return_4"] <= -0.005
            and features["vwap_distance"] >= 0
            and features["close_location_20"] <= -0.3
            and features["cross_sectional_return_rank_4"] <= -0.35
        ):
            return Route.LIQUIDITY_REVERSION
        return None


class QuoteSource(Protocol):
    def latest_quote(self, symbol: str) -> QuoteSnapshot: ...


class LiveTradingCycle:
    """Evaluates the incumbent and submits at most one protected equity entry."""

    MAX_ENTRY_NOTIONAL_RATE = Decimal("0.10")

    def __init__(
        self,
        *,
        store: OperationalStore,
        broker: PaperBroker,
        quotes: QuoteSource,
        strategy: IncumbentStrategy | None = None,
        risk_governor: RiskGovernor | None = None,
    ) -> None:
        self._store = store
        self._broker = broker
        self._quotes = quotes
        self._strategy = strategy or IncumbentStrategy()
        self._risk = risk_governor or RiskGovernor()
        self._gateway = ExecutionGateway(store=store, broker=broker)

    def run(
        self, vectors: tuple[FeatureVector, ...], *, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]:
        agent = self._store.get_agent_state()
        if agent.mode is not AgentMode.RUNNING:
            return ()
        if agent.execution_epoch != expected_epoch or not agent.is_reconciled:
            raise RuntimeError("worker lost execution epoch ownership")

        snapshot = self._broker.reconciliation_snapshot()
        if (
            not snapshot.clock.is_open
            or snapshot.account.trading_blocked
            or snapshot.positions
            or snapshot.open_orders
        ):
            return ()

        last_equity = snapshot.account.last_equity or snapshot.account.equity
        portfolio = PortfolioRiskState(
            equity=snapshot.account.equity,
            buying_power=min(
                snapshot.account.buying_power,
                snapshot.account.equity * self.MAX_ENTRY_NOTIONAL_RATE,
            ),
            position_count=0,
            total_open_risk=Decimal("0"),
            overnight_open_risk=Decimal("0"),
            group_open_risk={},
            daily_pnl=snapshot.account.equity - last_equity,
            competition_drawdown=max(
                Decimal("0"),
                (last_equity - snapshot.account.equity) / last_equity,
            ),
        )
        for vector in sorted(vectors, key=lambda item: item.symbol):
            if self._strategy.route(vector) is None:
                continue
            quote = self._quotes.latest_quote(vector.symbol)
            intent = self._strategy.create_intent(vector, quote)
            if intent is None:
                continue
            risk = self._risk.evaluate(
                intent,
                agent,
                portfolio,
                market_is_open=snapshot.clock.is_open,
                trading_blocked=snapshot.account.trading_blocked,
            )
            if risk.status is RiskDecisionStatus.VETOED:
                return self._persist_risk_veto(intent, risk, expected_epoch)
            execution = self._gateway.execute(intent, risk, expected_epoch=expected_epoch)
            return self._persist_execution(intent, risk, execution, expected_epoch)
        return ()

    def _persist_risk_veto(
        self, intent: TradeIntent, risk: RiskDecision, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]:
        record = DecisionRecord.create(
            decision_id=str(uuid5(NAMESPACE_URL, f"risk-veto:{intent.intent_id}")),
            decision_type="RISK_VETO",
            route=intent.route,
            symbol=intent.symbol,
            summary="; ".join(risk.checks),
            payload={"intent_id": intent.intent_id, "checks": risk.checks},
            public=True,
            public_summary=f"Risk governor vetoed {intent.symbol}",
        )
        return (
            (record,)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch)
            else ()
        )

    def _persist_execution(
        self,
        intent: TradeIntent,
        risk: RiskDecision,
        execution: OrderExecution,
        expected_epoch: str,
    ) -> tuple[DecisionRecord, ...]:
        record = DecisionRecord.create(
            decision_id=str(
                uuid5(NAMESPACE_URL, f"order-execution:{execution.plan.client_order_id}")
            ),
            decision_type="ORDER_EXECUTION",
            route=intent.route,
            symbol=intent.symbol,
            summary=(
                f"{execution.status} paper bracket {execution.plan.client_order_id} "
                f"for {execution.plan.quantity} {intent.symbol}"
            ),
            payload={
                "client_order_id": execution.plan.client_order_id,
                "status": execution.status,
                "quantity": execution.plan.quantity,
                "risk_amount": str(risk.risk_amount),
                "limit_price": str(execution.plan.limit_price),
                "stop_price": str(execution.plan.stop_price),
                "take_profit_price": str(execution.plan.take_profit_price),
            },
            public=True,
            public_summary=f"Paper bracket order {execution.status.lower()} for {intent.symbol}",
        )
        return (
            (record,)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch)
            else ()
        )


class ExecutionGateway:
    def __init__(self, *, store: OperationalStore, broker: PaperBroker) -> None:
        self._store = store
        self._broker = broker

    def execute(
        self,
        intent: TradeIntent,
        risk: RiskDecision,
        *,
        expected_epoch: str,
    ) -> OrderExecution:
        if risk.intent_id != intent.intent_id or risk.status is RiskDecisionStatus.VETOED:
            raise ValueError("an approved risk decision matching the intent is required")
        plan = self._plan(intent, risk)
        prepared = OrderExecution(plan=plan, request_hash=self._request_hash(plan))
        claimed = self._store.claim_order(prepared, expected_epoch=expected_epoch)
        execution = prepared if claimed else self._store.get_order(plan.client_order_id)
        if execution is None:
            raise RuntimeError("claimed order execution could not be loaded")
        if execution.request_hash != prepared.request_hash:
            raise RuntimeError("client order id was reused with a different request")
        if execution.status in {
            OrderExecutionStatus.ACKNOWLEDGED,
            OrderExecutionStatus.REJECTED,
        }:
            return execution

        broker_order = self._broker.get_order_by_client_id(plan.client_order_id)
        if broker_order is not None:
            return self._acknowledge(execution, broker_order)
        try:
            broker_order = self._broker.submit_order(plan)
        except Exception:
            broker_order = self._broker.get_order_by_client_id(plan.client_order_id)
            if broker_order is not None:
                return self._acknowledge(execution, broker_order)
            return self._transition(execution, OrderExecutionStatus.UNKNOWN)
        return self._acknowledge(execution, broker_order)

    @staticmethod
    def _plan(intent: TradeIntent, risk: RiskDecision) -> OrderPlan:
        client_order_id = "cr-" + uuid5(NAMESPACE_URL, f"paper-order-v1:{intent.intent_id}").hex
        take_profit = (intent.entry_price * Decimal("1.04")).quantize(_CENT, rounding=ROUND_CEILING)
        return OrderPlan(
            client_order_id=client_order_id,
            intent_id=intent.intent_id,
            symbol=intent.symbol,
            side=intent.side,
            quantity=risk.quantity,
            limit_price=intent.entry_price,
            stop_price=intent.stop_price,
            take_profit_price=take_profit,
            risk_amount=risk.risk_amount,
            exposure_group=intent.exposure_group,
        )

    @staticmethod
    def _request_hash(plan: OrderPlan) -> str:
        request = {
            "client_order_id": plan.client_order_id,
            "limit_price": str(plan.limit_price),
            "quantity": plan.quantity,
            "side": plan.side,
            "stop_price": str(plan.stop_price),
            "symbol": plan.symbol,
            "take_profit_price": str(plan.take_profit_price),
            "time_in_force": "day",
            "type": "limit",
        }
        encoded = json.dumps(request, sort_keys=True, separators=(",", ":")).encode()
        return hashlib.sha256(encoded).hexdigest()

    def _acknowledge(
        self, execution: OrderExecution, broker_order: BrokerOrderSnapshot
    ) -> OrderExecution:
        plan = execution.plan
        if (
            broker_order.client_order_id != plan.client_order_id
            or broker_order.symbol != plan.symbol
            or broker_order.side is not plan.side
            or broker_order.quantity != plan.quantity
        ):
            raise RuntimeError("Alpaca order does not match the durable order plan")
        return self._transition(
            execution,
            OrderExecutionStatus.ACKNOWLEDGED,
            alpaca_order_id=broker_order.order_id,
            broker_status=broker_order.status,
        )

    def _transition(
        self,
        execution: OrderExecution,
        status: OrderExecutionStatus,
        *,
        alpaca_order_id: str | None = None,
        broker_status: str | None = None,
    ) -> OrderExecution:
        updated = execution.model_copy(
            update={
                "status": status,
                "version": execution.version + 1,
                "alpaca_order_id": alpaca_order_id or execution.alpaca_order_id,
                "broker_status": broker_status or execution.broker_status,
                "updated_at": datetime.now(UTC),
            }
        )
        return self._store.update_order(updated, expected_status=execution.status)

from __future__ import annotations

import logging
import time
from collections.abc import Callable
from pathlib import Path
from typing import Protocol
from uuid import NAMESPACE_URL, uuid5

from catalyst_router.challenger import PublicChallengerStatus, ShadowPrediction
from catalyst_router.domain import DecisionRecord
from catalyst_router.ports import OperationalStore
from catalyst_router.training import FeatureVector, MarketBar, build_feature_vectors

logger = logging.getLogger(__name__)


class MarketData(Protocol):
    def recent_bars(
        self,
        symbols: tuple[str, ...],
        *,
        timeframe_minutes: int,
        lookback_days: int,
    ) -> list[MarketBar]: ...


class ChallengerPredictor(Protocol):
    status: PublicChallengerStatus
    symbols: tuple[str, ...]

    def predict(self, vector: FeatureVector) -> ShadowPrediction: ...


class FeatureBuilder(Protocol):
    def build(self, bars: list[MarketBar]) -> tuple[FeatureVector, ...]: ...


class LiveTrader(Protocol):
    def run(
        self, vectors: tuple[FeatureVector, ...], *, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]: ...


class LiveFeatureBuilder:
    def build(self, bars: list[MarketBar]) -> tuple[FeatureVector, ...]:
        return build_feature_vectors(bars)


class TradingWorker:
    """Runs the always-on inference cycle; execution remains separately gated."""

    def __init__(
        self,
        *,
        store: OperationalStore,
        market_data: MarketData,
        challenger: ChallengerPredictor,
        feature_builder: FeatureBuilder | None = None,
        live_trader: LiveTrader | None = None,
    ) -> None:
        self._store = store
        self._market_data = market_data
        self._challenger = challenger
        self._feature_builder = feature_builder or LiveFeatureBuilder()
        self._live_trader = live_trader
        self._execution_epoch: str | None = None

    def run_cycle(self) -> tuple[DecisionRecord, ...]:
        state = self._store.get_agent_state()
        if not state.is_reconciled:
            raise RuntimeError("worker execution epoch is not reconciled")
        if self._execution_epoch is not None and state.execution_epoch != self._execution_epoch:
            raise RuntimeError("worker lost execution epoch ownership")
        if not self._challenger.status.deployed or not self._challenger.status.loaded:
            raise RuntimeError("challenger is not ready for inference")
        timeframe = self._challenger.status.timeframe_minutes or 15
        bars = self._market_data.recent_bars(
            self._challenger.symbols,
            timeframe_minutes=timeframe,
            lookback_days=10,
        )
        vectors = self._feature_builder.build(bars)
        if not vectors:
            return ()
        latest = max(vector.observed_at for vector in vectors)
        expected_epoch = self._execution_epoch or state.execution_epoch
        records = []
        for vector in vectors:
            if vector.observed_at != latest:
                continue
            prediction = self._challenger.predict(vector)
            record = self._prediction_record(prediction)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch):
                records.append(record)
        if self._live_trader is not None:
            latest_vectors = tuple(vector for vector in vectors if vector.observed_at == latest)
            records.extend(self._live_trader.run(latest_vectors, expected_epoch=expected_epoch))
        return tuple(records)

    def run_forever(
        self,
        *,
        reconcile: Callable[[], object],
        poll_seconds: int = 60,
        sleep: Callable[[float], None] = time.sleep,
        heartbeat_path: Path = Path("/tmp/worker-heartbeat"),
    ) -> None:
        reconcile()
        state = self._store.get_agent_state()
        if not state.is_reconciled:
            raise RuntimeError("startup reconciliation did not complete")
        self._execution_epoch = state.execution_epoch
        consecutive_failures = 0
        while True:
            try:
                records = self.run_cycle()
                consecutive_failures = 0
                if records:
                    logger.info("persisted %d challenger predictions", len(records))
                heartbeat_path.touch()
            except Exception:
                consecutive_failures += 1
                logger.exception("trading worker cycle failed")
                if consecutive_failures >= 5:
                    raise
            sleep(poll_seconds)

    def _prediction_record(self, prediction: ShadowPrediction) -> DecisionRecord:
        decision_id = str(
            uuid5(
                NAMESPACE_URL,
                ":".join(
                    (
                        "challenger-prediction",
                        prediction.run_id,
                        prediction.symbol,
                        prediction.observed_at.isoformat(),
                    )
                ),
            )
        )
        return DecisionRecord.create(
            decision_id=decision_id,
            decision_type="CHALLENGER_PREDICTION",
            occurred_at=prediction.observed_at,
            symbol=prediction.symbol,
            summary=(
                f"shadow model {prediction.run_id} predicted {prediction.value:.6f} "
                f"({prediction.signal})"
            ),
            payload={
                "authority": "SHADOW_ONLY",
                "run_id": prediction.run_id,
                "value": prediction.value,
                "signal": prediction.signal,
            },
            public=True,
            public_summary=f"Shadow model signal: {prediction.signal}",
        )

from __future__ import annotations

from datetime import UTC, datetime, timedelta
from threading import RLock
from uuid import uuid4

from catalyst_router.domain import (
    AgentMode,
    AgentState,
    DecisionRecord,
    OrderExecution,
    OrderExecutionStatus,
    PublicDecisionRecord,
)


class InMemoryOperationalStore:
    def __init__(self, public_delay_seconds: int = 0) -> None:
        self._lock = RLock()
        self._state: AgentState | None = None
        self._decisions: dict[str, DecisionRecord] = {}
        self._orders: dict[str, OrderExecution] = {}
        self._public_delay = timedelta(seconds=public_delay_seconds)

    def initialize(self) -> AgentState:
        with self._lock:
            if self._state is None:
                self._state = AgentState()
            return self._state

    def get_agent_state(self) -> AgentState:
        with self._lock:
            return self.initialize()

    def begin_execution(self) -> AgentState:
        with self._lock:
            state = self.initialize()
            self._state = state.model_copy(
                update={
                    "version": state.version + 1,
                    "execution_epoch": str(uuid4()),
                    "reconciled_epoch": None,
                    "updated_at": datetime.now(UTC),
                }
            )
            return self._state

    def transition_agent_mode(
        self, mode: AgentMode, *, reason: str, record: DecisionRecord
    ) -> AgentState:
        with self._lock:
            state = self.initialize()
            if state.mode is AgentMode.KILLED:
                raise RuntimeError("KILLED agent mode is terminal")
            if mode is AgentMode.RUNNING and not state.is_reconciled:
                raise RuntimeError("startup reconciliation is required before RUNNING")
            if record.decision_id in self._decisions:
                raise ValueError(f"decision already exists: {record.decision_id}")
            self._state = state.model_copy(
                update={
                    "mode": mode,
                    "reason": reason,
                    "version": state.version + 1,
                    "updated_at": datetime.now(UTC),
                }
            )
            self._decisions[record.decision_id] = record
            return self._state

    def commit_reconciliation(self, epoch: str, record: DecisionRecord) -> AgentState:
        with self._lock:
            state = self.initialize()
            if state.execution_epoch != epoch:
                raise RuntimeError("execution epoch changed during reconciliation")
            if record.decision_id in self._decisions:
                raise ValueError(f"decision already exists: {record.decision_id}")
            self._state = state.model_copy(
                update={
                    "version": state.version + 1,
                    "reconciled_epoch": epoch,
                    "updated_at": datetime.now(UTC),
                }
            )
            self._decisions[record.decision_id] = record
            return self._state

    def append_decision(self, record: DecisionRecord) -> None:
        with self._lock:
            if record.decision_id in self._decisions:
                raise ValueError(f"decision already exists: {record.decision_id}")
            self._decisions[record.decision_id] = record

    def append_decision_once(
        self, record: DecisionRecord, *, expected_epoch: str | None = None
    ) -> bool:
        with self._lock:
            state = self.initialize()
            if expected_epoch is not None and (
                state.execution_epoch != expected_epoch or not state.is_reconciled
            ):
                raise RuntimeError("worker lost execution epoch ownership")
            if record.decision_id in self._decisions:
                return False
            self._decisions[record.decision_id] = record
            return True

    def claim_order(self, execution: OrderExecution, *, expected_epoch: str) -> bool:
        with self._lock:
            state = self.initialize()
            if (
                state.mode is not AgentMode.RUNNING
                or state.execution_epoch != expected_epoch
                or not state.is_reconciled
            ):
                raise RuntimeError("agent is not authorized for new exposure")
            client_order_id = execution.plan.client_order_id
            if client_order_id in self._orders:
                return False
            self._orders[client_order_id] = execution
            return True

    def get_order(self, client_order_id: str) -> OrderExecution | None:
        with self._lock:
            return self._orders.get(client_order_id)

    def update_order(
        self,
        execution: OrderExecution,
        *,
        expected_status: OrderExecutionStatus,
    ) -> OrderExecution:
        with self._lock:
            client_order_id = execution.plan.client_order_id
            current = self._orders.get(client_order_id)
            if current is None:
                raise RuntimeError("order execution does not exist")
            if current.status is not expected_status or execution.version != current.version + 1:
                raise RuntimeError("order execution changed concurrently")
            self._orders[client_order_id] = execution
            return execution

    def list_public_decisions(self, limit: int = 50) -> list[PublicDecisionRecord]:
        with self._lock:
            now = datetime.now(UTC)
            records = [
                record
                for record in self._decisions.values()
                if record.public and record.occurred_at + self._public_delay <= now
            ]
            selected = sorted(records, key=lambda record: record.occurred_at, reverse=True)[:limit]
            return [record.public_projection() for record in selected]

from decimal import ROUND_FLOOR, Decimal

from catalyst_router.domain import (
    AgentMode,
    AgentState,
    InstrumentType,
    PortfolioRiskState,
    RiskDecision,
    RiskDecisionStatus,
    Route,
    Side,
    TradeIntent,
)


class RiskGovernor:
    MAX_POSITIONS = 6
    MAX_TRADE_RISK_RATE = Decimal("0.01")
    REDUCED_TRADE_RISK_RATE = Decimal("0.005")
    MAX_TOTAL_RISK_RATE = Decimal("0.04")
    MAX_OVERNIGHT_RISK_RATE = Decimal("0.02")
    MAX_GROUP_RISK_RATE = Decimal("0.02")
    DE_RISK_DAILY_LOSS_RATE = Decimal("0.02")
    MAX_DAILY_LOSS_RATE = Decimal("0.04")
    MAX_COMPETITION_DRAWDOWN_RATE = Decimal("0.12")
    MAX_QUOTE_AGE_SECONDS = Decimal("5")

    def __init__(self, *, options_execution_enabled: bool = False) -> None:
        self._options_execution_enabled = options_execution_enabled

    def evaluate(
        self,
        intent: TradeIntent,
        agent: AgentState,
        portfolio: PortfolioRiskState,
        *,
        market_is_open: bool,
        overnight: bool = False,
        trading_blocked: bool = False,
    ) -> RiskDecision:
        vetoes: list[str] = []
        if intent.route is Route.NO_TRADE:
            vetoes.append("NO_TRADE cannot create exposure")
        if intent.instrument_type is InstrumentType.OPTION and intent.side is not Side.BUY:
            vetoes.append("short option legs are prohibited")
        if intent.instrument_type is InstrumentType.OPTION and not self._options_execution_enabled:
            vetoes.append("live option execution is not enabled")
        if intent.route is Route.LIQUIDITY_REVERSION and (
            intent.instrument_type is not InstrumentType.EQUITY
        ):
            vetoes.append("liquidity reversion must use equities")
        if intent.route is Route.REGIME_TREND and (
            intent.instrument_type is not InstrumentType.EQUITY
        ):
            vetoes.append("regime trend must use equities")
        if trading_blocked:
            vetoes.append("Alpaca account is blocked from trading")
        if agent.mode is not AgentMode.RUNNING:
            vetoes.append(f"agent mode is {agent.mode}")
        if not agent.is_reconciled:
            vetoes.append("startup reconciliation is incomplete")
        if not market_is_open:
            vetoes.append("market is closed")
        if not intent.data_quality_passed:
            vetoes.append("intent data failed quality gates")
        if intent.quote_age_seconds > self.MAX_QUOTE_AGE_SECONDS:
            vetoes.append("quote is stale")
        if intent.stop_distance <= 0:
            vetoes.append("stop distance must be positive")
        if intent.side is Side.BUY and intent.stop_price >= intent.entry_price:
            vetoes.append("buy stop must be below entry")
        if intent.side is Side.SELL and intent.stop_price <= intent.entry_price:
            vetoes.append("sell stop must be above entry")
        if portfolio.position_count >= self.MAX_POSITIONS:
            vetoes.append("maximum position count reached")

        daily_loss = max(Decimal("0"), -portfolio.daily_pnl)
        if daily_loss >= portfolio.equity * self.MAX_DAILY_LOSS_RATE:
            vetoes.append("daily loss circuit breaker reached")
        if portfolio.competition_drawdown >= self.MAX_COMPETITION_DRAWDOWN_RATE:
            vetoes.append("competition drawdown kill threshold reached")

        if vetoes:
            return self._veto(intent, vetoes)

        risk_rate = (
            self.REDUCED_TRADE_RISK_RATE
            if daily_loss >= portfolio.equity * self.DE_RISK_DAILY_LOSS_RATE
            else self.MAX_TRADE_RISK_RATE
        )
        allowed_risk = portfolio.equity * risk_rate
        total_capacity = portfolio.equity * self.MAX_TOTAL_RISK_RATE - portfolio.total_open_risk
        group_capacity = (
            portfolio.equity * self.MAX_GROUP_RISK_RATE
            - portfolio.group_open_risk.get(intent.exposure_group, Decimal("0"))
        )
        capacities = [allowed_risk, total_capacity, group_capacity]
        if overnight:
            capacities.append(
                portfolio.equity * self.MAX_OVERNIGHT_RISK_RATE - portfolio.overnight_open_risk
            )
        risk_amount = max(Decimal("0"), min(capacities))
        affordable = (portfolio.buying_power / intent.entry_cost_per_unit).to_integral_value(
            rounding=ROUND_FLOOR
        )
        by_stop = (risk_amount / intent.stop_risk_per_unit).to_integral_value(rounding=ROUND_FLOOR)
        quantity = int(min(affordable, by_stop))
        if quantity < 1:
            return self._veto(intent, ["risk or buying-power capacity is insufficient"])

        actual_risk = intent.stop_risk_per_unit * quantity
        status = (
            RiskDecisionStatus.REDUCED
            if risk_amount < allowed_risk or risk_rate < self.MAX_TRADE_RISK_RATE
            else RiskDecisionStatus.APPROVED
        )
        return RiskDecision(
            status=status,
            intent_id=intent.intent_id,
            quantity=quantity,
            risk_amount=actual_risk,
            checks=(
                "agent running and reconciled",
                "data and market gates passed",
                "trade, portfolio, group, and buying-power limits passed",
            ),
        )

    @staticmethod
    def _veto(intent: TradeIntent, vetoes: list[str]) -> RiskDecision:
        return RiskDecision(
            status=RiskDecisionStatus.VETOED,
            intent_id=intent.intent_id,
            quantity=0,
            risk_amount=Decimal("0"),
            checks=tuple(vetoes),
        )

from __future__ import annotations

from datetime import UTC, datetime, timedelta

from catalyst_router.domain import DecisionRecord, ReconciliationSnapshot
from catalyst_router.ports import OperationalStore, PaperBroker


class ReconciliationService:
    def __init__(self, *, broker: PaperBroker, store: OperationalStore) -> None:
        self._broker = broker
        self._store = store

    def reconcile(self) -> ReconciliationSnapshot:
        state = self._store.begin_execution()
        snapshot = self._broker.reconciliation_snapshot()
        self.validate_snapshot(snapshot)
        record = DecisionRecord.create(
            decision_type="RECONCILIATION_COMPLETED",
            summary=(
                f"Reconciled {len(snapshot.positions)} positions and "
                f"{len(snapshot.open_orders)} open orders"
            ),
            payload={
                "market_is_open": snapshot.clock.is_open,
                "position_count": len(snapshot.positions),
                "open_order_count": len(snapshot.open_orders),
                "options_trading_level": snapshot.account.options_trading_level,
            },
            public=True,
            public_summary=(
                f"Reconciled {len(snapshot.positions)} positions and "
                f"{len(snapshot.open_orders)} open orders"
            ),
        )
        self._store.commit_reconciliation(state.execution_epoch, record)
        return snapshot

    @staticmethod
    def validate_snapshot(snapshot: ReconciliationSnapshot) -> None:
        now = datetime.now(UTC)
        if snapshot.account.trading_blocked:
            raise RuntimeError("Alpaca account is blocked from trading")
        if snapshot.account.equity <= 0 or snapshot.account.portfolio_value <= 0:
            raise RuntimeError("Alpaca account values are invalid")
        if not now - timedelta(seconds=30) <= snapshot.captured_at <= now + timedelta(seconds=5):
            raise RuntimeError("Alpaca reconciliation snapshot is stale")
        if len(snapshot.open_orders) >= 500:
            raise RuntimeError("open-order response may be truncated")

